// --- Utilidades comunes de EventPass ------------------------------------
const ahora = () => new Date().toISOString();
const nuevoId = (prefijo) =>
  prefijo + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const norm = (v) => String(v ?? '').trim();
const normEmail = (v) => norm(v).toLowerCase();
// Lee todas las filas de un nodo de Google Sheets ignorando el item vacío que produce "Always Output Data".
const filas = (nodo) => {
  try {
    return $(nodo).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
};
const fallo = (status, mensaje, extra = {}) => [{ json: { ok: false, status, body: { ok: false, error: mensaje }, ...extra } }];
// Convierte cualquiera de los 4 formularios a una solicitud normalizada.
const f = $input.first().json;
const campo = (k) => norm(f[k]);
const err = (mensaje) => [{ json: { ok: false, mensaje } }];
let accion;
if ('Nuevo estado' in f) accion = 'ESTADO';
else if ('Estado inicial' in f) accion = 'CREAR';
else if ('Disciplina' in f) accion = 'ACTUALIZAR';
else accion = 'CONSULTAR';

const datos = {
  nombre: campo('Nombre del evento'),
  categoria: campo('Disciplina'),
  grupo_edad: campo('Grupo de edad'),
  descripcion: campo('Descripción'),
  fecha: campo('Fecha'),
  hora: campo('Hora (HH:MM, 24 h)'),
  lugar: campo('Lugar'),
  capacidad: campo('Capacidad'),
  imagen_url: campo('URL de imagen'),
  organizador: campo('Organizador'),
};
if (datos.hora) {
  const m = datos.hora.match(/^(\d{1,2}):(\d{2})$/);
  if (!m || +m[1] > 23 || +m[2] > 59) return err('La hora debe tener el formato HH:MM en 24 horas, por ejemplo 07:30.');
  datos.hora = m[1].padStart(2, '0') + ':' + m[2];
}
if (datos.fecha && !/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)) return err('La fecha no es válida.');
if (datos.capacidad) {
  const n = Number(datos.capacidad);
  if (!Number.isInteger(n) || n < 1 || n > 5000) return err('La capacidad debe ser un número entero entre 1 y 5000.');
  datos.capacidad = String(n);
}
if (datos.imagen_url && !/^https?:\/\//.test(datos.imagen_url)) return err('La URL de imagen debe empezar por http:// o https://.');
if (accion === 'CREAR') {
  for (const k of ['nombre', 'categoria', 'grupo_edad', 'descripcion', 'fecha', 'hora', 'lugar', 'capacidad', 'organizador']) {
    if (!datos[k]) return err('Falta el campo: ' + k);
  }
}
return [{ json: {
  ok: true,
  accion,
  evento_id: campo('ID del evento').toUpperCase(),
  estado_inicial: campo('Estado inicial'),
  nuevo_estado: campo('Nuevo estado'),
  motivo: campo('Motivo'),
  datos,
} }];

