// --- Utilidades comunes de EventPass ------------------------------------
const ahora = () => new Date().toISOString();
const nuevoId = (prefijo) =>
  prefijo + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
