  try {
    return $(nodo).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
};
const fallo = (status, mensaje, extra = {}) => [{ json: { ok: false, status, body: { ok: false, error: mensaje }, ...extra } }];
// --- Utilidades de eventos e inscripciones ------------------------------
const ZONA_HORARIA = '-05:00'; // Hora de Colombia
function inicioEvento(evento) {
  const [h = '00', m = '00'] = norm(evento.hora).split(':');
  return new Date(`${norm(evento.fecha)}T${h.padStart(2, '0')}:${m.padStart(2, '0')}:00${ZONA_HORARIA}`);
}
const ESTADOS_ACTIVOS = ['CONFIRMADA', 'LISTA_ESPERA'];
function confirmadasDe(inscripciones, eventoId) {
  return inscripciones.filter((i) => i.evento_id === eventoId && i.estado === 'CONFIRMADA').length;
}
function listaEsperaDe(inscripciones, eventoId) {
  return inscripciones
    .filter((i) => i.evento_id === eventoId && i.estado === 'LISTA_ESPERA')
    .sort((a, b) => norm(a.fecha_inscripcion).localeCompare(norm(b.fecha_inscripcion)));
}
const fechaLegible = (evento) => {
  const d = inicioEvento(evento);
  if (isNaN(d)) return `${evento.fecha} ${evento.hora}`;
  return d.toLocaleString('es-CO', {
    timeZone: 'America/Bogota', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
  });
};
const s = $('Validar formulario').first().json;
const eventos = filas('Leer Eventos').filter((e) => e.evento_id);
const inscripciones = filas('Leer Inscripciones');
const resumen = (e) => {
  const conf = confirmadasDe(inscripciones, e.evento_id);
  return `${e.evento_id} · ${e.nombre} (${e.categoria}, ${e.grupo_edad}) — ${e.fecha} ${e.hora} — ${e.estado} — ${conf}/${e.capacidad} confirmados, ${listaEsperaDe(inscripciones, e.evento_id).length} en espera`;
};
if (s.evento_id) {
  const e = eventos.find((x) => x.evento_id === s.evento_id);
  if (!e) return [{ json: { ok: false, mensaje: 'No existe un evento con el ID ' + s.evento_id } }];
  return [{ json: { ok: true, titulo: e.nombre, mensaje: resumen(e) + (e.motivo_estado ? ` — Motivo: ${e.motivo_estado}` : '') + `\n\nLugar: ${e.lugar}\nOrganiza: ${e.organizador}\n\n${e.descripcion}` } }];
}
const lista = eventos.sort((a, b) => inicioEvento(a) - inicioEvento(b)).map(resumen);
return [{ json: { ok: true, titulo: `${lista.length} eventos registrados`, mensaje: lista.join('\n') || 'Aún no hay eventos.' } }];

