if (!e) return [{ json: { ok: false, mensaje: 'No existe un evento con el ID ' + s.evento_id } }];
if (e.estado === 'CANCELADO') return [{ json: { ok: false, mensaje: 'Un evento cancelado no se puede editar.' } }];
const cambios = Object.entries(s.datos).filter(([k, v]) => v && v !== norm(e[k]));
if (cambios.length === 0) return [{ json: { ok: false, mensaje: 'No escribiste ningún cambio.' } }];
const nuevo = { ...e, ...Object.fromEntries(cambios), fecha_actualizacion: ahora() };
const confirmadas = confirmadasDe(filas('Leer Inscripciones'), e.evento_id);
if (Number(nuevo.capacidad) < confirmadas) {
  return [{ json: { ok: false, mensaje: `La capacidad no puede ser menor que las ${confirmadas} inscripciones confirmadas.` } }];
}
const campos = cambios.map(([k]) => k);
const logistica = campos.some((k) => ['fecha', 'hora', 'lugar'].includes(k));
return [{ json: {
